    public static final DeferredItem<net.minecraft.world.item.Item> RUNIC_KEY=ITEMS.registerSimpleItem("runic_key",new net.minecraft.world.item.Item.Properties().rarity(net.minecraft.world.item.Rarity.RARE));
    public static final Map<String,DeferredItem<CultistArmorItem>> CULTIST_ARMOR=new LinkedHashMap<>();
    static{for(var kind:List.of(CultistArmorItem.Kind.PLATE,CultistArmorItem.Kind.ROBE,CultistArmorItem.Kind.LEADER))for(var type:List.of(net.minecraft.world.item.ArmorItem.Type.HELMET,net.minecraft.world.item.ArmorItem.Type.CHESTPLATE,net.minecraft.world.item.ArmorItem.Type.LEGGINGS)){String name="cultist_"+kind.name().toLowerCase(Locale.ROOT)+"_"+type.getName();CULTIST_ARMOR.put(name,ITEMS.register(name,()->new CultistArmorItem(type,kind)));}CULTIST_ARMOR.put("cultist_boots",ITEMS.register("cultist_boots",()->new CultistArmorItem(net.minecraft.world.item.ArmorItem.Type.BOOTS,CultistArmorItem.Kind.BOOTS)));}
    public static final DeferredBlock<thaumcraft.blocks.EldritchVoidBlock> ELDRITCH_VOID=BLOCKS.register("eldritch_void",thaumcraft.blocks.EldritchVoidBlock::new);
    public static final DeferredHolder<net.minecraft.world.level.block.entity.BlockEntityType<?>,net.minecraft.world.level.block.entity.BlockEntityType<thaumcraft.blocks.EldritchVoidBlockEntity>> VOID_ENTITY=TILES.register("eldritch_void",()->net.minecraft.world.level.block.entity.BlockEntityType.Builder.of((pos,state)->state.is(ELDRITCH_VOID.get())&&state.getValue(thaumcraft.blocks.EldritchVoidBlock.EXPOSED)?new thaumcraft.blocks.EldritchVoidBlockEntity(pos,state):null,ELDRITCH_VOID.get()).build(null));
    public static final DeferredBlock<net.minecraft.world.level.block.SlabBlock> ELDRITCH_SLAB=BLOCKS.register("eldritch_stone_slab",()->new net.minecraft.world.level.block.SlabBlock(net.minecraft.world.level.block.state.BlockBehaviour.Properties.of().strength(2,6).sound(net.minecraft.world.level.block.SoundType.STONE)));
    public static final DeferredItem<net.minecraft.world.item.BlockItem> ELDRITCH_SLAB_ITEM=ITEMS.registerSimpleBlockItem(ELDRITCH_SLAB);
    public static final DeferredBlock<net.minecraft.world.level.block.Block> ELDRITCH_STONE=stone("eldritch_stone",false,0),ELDRITCH_ROCK=stone("eldritch_rock",false,0),ELDRITCH_STONE_NOSPAWN=stone("eldritch_stone_nospawn",true,0),ANCIENT_STONE=stone("ancient_stone",false,4),ELDRITCH_PILLAR=stone("eldritch_pillar",false,0);
    public static final DeferredBlock<net.minecraft.world.level.block.StairBlock> ELDRITCH_STAIRS=BLOCKS.register("eldritch_stone_stairs",()->new net.minecraft.world.level.block.StairBlock(ELDRITCH_STONE.get().defaultBlockState(),net.minecraft.world.level.block.state.BlockBehaviour.Properties.ofFullCopy(ELDRITCH_STONE.get())));
    static {for(var block:List.of(ELDRITCH_STONE,ELDRITCH_ROCK,ELDRITCH_STONE_NOSPAWN,ANCIENT_STONE,ELDRITCH_PILLAR,ELDRITCH_STAIRS))ITEMS.registerSimpleBlockItem(block);}
    public static final DeferredBlock<AncientLootBlock> LOOT_URN=BLOCKS.register("loot_urn",()->new AncientLootBlock(false)),LOOT_CRATE=BLOCKS.register("loot_crate",()->new AncientLootBlock(true));
    public static final DeferredItem<AncientLootBlockItem> URN_ITEM=ITEMS.register("loot_urn",()->new AncientLootBlockItem(LOOT_URN.get())),CRATE_ITEM=ITEMS.register("loot_crate",()->new AncientLootBlockItem(LOOT_CRATE.get()));
    public static final List<DeferredItem<AncientLootBagItem>> LOOT_BAGS=new ArrayList<>();
    public static final List<DeferredItem<AspectDiscountRingItem>> DISCOUNT_RINGS=new ArrayList<>();
    static{for(int rarity=0;rarity<3;rarity++){final int r=rarity;LOOT_BAGS.add(ITEMS.register(new String[]{"common","uncommon","rare"}[r]+"_loot_bag",()->new AncientLootBagItem(r)));}for(var aspect:List.of(Aspects.AIR,Aspects.EARTH,Aspects.FIRE,Aspects.WATER,Aspects.ORDER,Aspects.ENTROPY)){String name=new String[]{"air","earth","fire","water","order","entropy"}[DISCOUNT_RINGS.size()];DISCOUNT_RINGS.add(ITEMS.register(name+"_discount_ring",()->new AspectDiscountRingItem(aspect)));}}
    public static void register(IEventBus bus){BLOCKS.register(bus);ITEMS.register(bus);TILES.register(bus);MENUS.register(bus);}
    public static void creative(CreativeModeTab.Output out){for(var b:List.of(ELDRITCH_STONE,ELDRITCH_ROCK,ANCIENT_STONE,ELDRITCH_PILLAR,ELDRITCH_STAIRS,ELDRITCH_SLAB,CARVED_STONE))out.accept(b.get());out.accept(RUNIC_KEY.get());out.accept(CRIMSON_SWORD.get());out.accept(VISHROOM.get());out.accept(MANA_BEAN.get());out.accept(PECH_FOCUS.get());for(var armor:CULTIST_ARMOR.values())out.accept(armor.get());for(int r=0;r<3;r++){out.accept(AncientLootBlockItem.stack(LOOT_URN.get(),r));out.accept(AncientLootBlockItem.stack(LOOT_CRATE.get(),r));out.accept(LOOT_BAGS.get(r));}}
    private static DeferredBlock<net.minecraft.world.level.block.Block> stone(String name,boolean noSpawn,int light){var properties=net.minecraft.world.level.block.state.BlockBehaviour.Properties.of().strength(2,6).sound(net.minecraft.world.level.block.SoundType.STONE).randomTicks().lightLevel(s->light);if(noSpawn)properties.isValidSpawn((s,l,p,type)->false);return BLOCKS.registerSimpleBlock(name,properties);}
    private R5Content(){}
